import { physiqueFor } from '@/lib/physique';

/*
 * Portraits generated by code (ADR 0010 §4: avatars, never photos): a flat
 * vector bust drawn from the seed. The same seed always yields the same
 * picture, and an athlete's skin and hair match his body in the 3D match
 * (`lib/physique`). No third-party artwork.
 *
 * The exported names keep the "pixel" of the previous art style so the
 * screens did not have to change with it.
 */

/** Background swatches: artwork colours, not UI tokens (hex without '#'). */
const BACKDROPS = ['1f3a5c', '12543a', '5a2a2e', '4d3c14', '2e2f5e', '1b4a54'];

export interface PixelAvatarOptions {
  /** Size of the SVG box in CSS pixels (the picture is vector). */
  readonly size?: number;
  /** Background hex without '#'; derived from the seed when omitted. */
  readonly backdrop?: string;
  /** Hide the backdrop (transparent picture). */
  readonly transparent?: boolean;
  /** Shirt colour (hex with '#'); a neutral training top when omitted. */
  readonly shirt?: string;
}

export function avatarBackdrop(seed: string): string {
  return BACKDROPS[physiqueFor(seed).variant % BACKDROPS.length]!;
}

function shade(hex: string, amount: number): string {
  const value = Number.parseInt(hex.replace('#', ''), 16) || 0;
  const channel = (shift: number) => {
    const base = (value >> shift) & 255;
    const next =
      amount < 0 ? base * (1 + amount) : base + (255 - base) * amount;
    return Math.max(0, Math.min(255, Math.round(next)))
      .toString(16)
      .padStart(2, '0');
  };
  return `#${channel(16)}${channel(8)}${channel(0)}`;
}

/** Hair shapes over a head centred at (32, 27), 11 wide and 13 tall. */
const HAIR = [
  // Short crop.
  'M21 25c0-9 5-13 11-13s11 4 11 13c-2-5-5-7-11-7s-9 2-11 7z',
  // Side part.
  'M20.5 27c-1-10 4-15.5 12-15.5 7 0 11.5 4.5 11 14-2-6-4-8-8-8.500-5 0-10 1-15 10z',
  // Curls.
  'M19 27c-3-4-1-9 2-10 0-4 4-7 8-6 2-2 7-2 9 0 4-1 8 3 7 7 3 2 3 6 0 9-1-5-3-8-6-9-3 1-9 1-13 0-4 1-6 4-7 9z',
  // Flat top.
  'M21 24v-9c0-2 2-3.500 4-3.500h14c2 0 4 1.500 4 3.500v9c-2-4-4-5.500-11-5.500s-9 1.500-11 5.500z',
  // Long fringe.
  'M20 30c-2-12 3-18.500 12-18.500 8 0 13 5.500 12 17-1-6-3-9-6-10-2 2-8 3-13 2-3 2-4 5-5 9.500z',
  // Shaved: only a shadow of hair.
  '',
] as const;

/** SVG markup of the deterministic portrait for `seed`. */
export function pixelAvatarSvg(
  seed: string,
  options: PixelAvatarOptions = {},
): string {
  const size = options.size ?? 64;
  // "atleta-<id>" and the bare id are the same person.
  const look = physiqueFor(seed.replace(/^atleta-/, ''));
  const bits = look.variant;
  const coach = seed.startsWith('treinador-');
  const backdrop = `#${options.backdrop ?? avatarBackdrop(seed)}`;
  const shirt = options.shirt ?? (coach ? '#1d232c' : '#2b3644');
  const skin = look.skin;
  const hair = HAIR[bits % HAIR.length]!;
  const beard = (bits >>> 3) % 4 === 0;
  const smile = (bits >>> 5) % 3;
  const id = `a${(bits % 46_655).toString(36)}`;
  const mouth =
    smile === 0
      ? 'M28.500 34.500q3.500 2.400 7 0'
      : smile === 1
        ? 'M29 35h6'
        : 'M28.500 35q3.500 1.200 7 0';
  return [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="${size}" height="${size}">`,
    `<defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1">`,
    `<stop offset="0" stop-color="${shade(backdrop, 0.22)}"/><stop offset="1" stop-color="${shade(backdrop, -0.45)}"/>`,
    `</linearGradient></defs>`,
    options.transparent
      ? ''
      : `<rect width="64" height="64" fill="url(#${id})"/><path d="M0 0h64L0 46z" fill="#fff" opacity=".05"/>`,
    // Shoulders, collar and neck.
    `<path d="M8 64c0-11 8-17 17-18.500l7 4 7-4c9 1.500 17 7.500 17 18.500z" fill="${shirt}"/>`,
    `<path d="M8 64c0-11 8-17 17-18.500l2 1.200C19 49 14 55 14 64z" fill="#000" opacity=".16"/>`,
    coach
      ? `<path d="M26.500 46l5.500 7 5.500-7-5.500 3z" fill="#eef2f6"/>`
      : `<path d="M25 45.500l7 4 7-4 1.500 1.800-8.500 5.200-8.500-5.200z" fill="${shade(shirt, 0.55)}"/>`,
    `<path d="M27 38h10v8.500l-5 3-5-3z" fill="${shade(skin, -0.16)}"/>`,
    // Ears and head.
    `<ellipse cx="20.800" cy="28" rx="2" ry="3" fill="${shade(skin, -0.1)}"/><ellipse cx="43.200" cy="28" rx="2" ry="3" fill="${shade(skin, -0.1)}"/>`,
    `<ellipse cx="32" cy="27" rx="11" ry="13" fill="${skin}"/>`,
    `<path d="M32 14c6 0 11 5.800 11 13s-5 13-11 13c4-3 6-7.500 6-13s-2-10-6-13z" fill="#000" opacity=".07"/>`,
    beard
      ? `<path d="M22 30c1 7 5 10.500 10 10.500S41 37 42 30c-2 3.500-5 5-10 5s-8-1.500-10-5z" fill="${look.hair}" opacity=".85"/>`
      : '',
    hair
      ? `<path d="${hair}" fill="${look.hair}"/>`
      : `<path d="M21.500 23c1-7 5-10.500 10.500-10.500S41.500 16 42.500 23c-3-5-6-6.500-10.500-6.500S24.500 18 21.500 23z" fill="${look.hair}" opacity=".35"/>`,
    // Face.
    `<path d="M25 24.500q2.500-1.300 5 0M34 24.500q2.500-1.300 5 0" stroke="${shade(look.hair, -0.2)}" stroke-width="1.300" fill="none" stroke-linecap="round"/>`,
    `<ellipse cx="27.500" cy="27.800" rx="1.300" ry="1.600" fill="#15181d"/><ellipse cx="36.500" cy="27.800" rx="1.300" ry="1.600" fill="#15181d"/>`,
    `<path d="M32 28.500v3.200l-1.300.800" stroke="${shade(skin, -0.28)}" stroke-width="1" fill="none" stroke-linecap="round"/>`,
    `<path d="${mouth}" stroke="${shade(skin, -0.45)}" stroke-width="1.300" fill="none" stroke-linecap="round"/>`,
    `</svg>`,
  ].join('');
}

/** `data:` URI of the portrait, ready for an `<img src>`. */
export function pixelAvatarUri(
  seed: string,
  options: PixelAvatarOptions = {},
): string {
  const svg = pixelAvatarSvg(seed, options);
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}
